import { FiExternalLink } from "react-icons/fi";
import { getEthereumProvider } from "../contract/contractClients";
import { buildMetaMaskDappLink, isMobileDevice } from "../utils/walletEnvironment";

export default function MetaMaskMobileLink({ url, providerAvailable }) {
    if (!isMobileDevice()) return null;
    if (providerAvailable ?? Boolean(getEthereumProvider?.())) return null;
    const href = buildMetaMaskDappLink(url || (typeof window !== "undefined" ? window.location.href : ""));
    if (!href) return null;
    return <div style={{ margin: "12px 0", overflowWrap: "anywhere", color: "var(--text-primary, #f1f5f9)" }}>
        <a className="btn-primary-custom" href={href} style={{ display: "inline-flex", alignItems: "center", gap: 8, maxWidth: "100%", whiteSpace: "normal", minHeight: 44 }}>
            <FiExternalLink aria-hidden="true" /> MetaMaskアプリで開く
        </a>
        <p style={{ marginTop: 8 }}>iPhone・iPadでは、MetaMaskアプリ内で接続・トークン追加・回答の承認を行ってください。</p>
    </div>;
}
